const motionStaticAssets:Readonly<Record<string,string>>={"developer-space":"developer-space-static-first-frame","developer-ability":"developer-ability-static-first-frame","developer-ability-mobile":"developer-ability-mobile-static-first-frame"};
function useReducedMotionPreference(){
 const query=()=>typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
 const [reduced,setReduced]=React.useState(query);
 React.useEffect(()=>{if(typeof matchMedia!=='function')return;const media=matchMedia('(prefers-reduced-motion: reduce)'),update=()=>setReduced(media.matches);update();media.addEventListener('change',update);return()=>media.removeEventListener('change',update)},[]);
 return reduced;
}
export function PortalAsset({assetId,alt,className=""}:{assetId:string;alt:string;className?:string}){const reduced=useReducedMotionPreference();return <img src={getPortalAssetUrl(reduced?(motionStaticAssets[assetId]??assetId):assetId)} alt={alt} className={className}/>;}

export function getPortalAssetUrl(id:string){if(!assets[id])throw Error('Unknown packaged asset: '+id);return assets[id]};
